-- Run once in a new Supabase project. All privileged mutations are SECURITY DEFINER
-- functions with fixed search_path and explicit role checks. No service key is needed.
begin;
create extension if not exists pgcrypto with schema extensions;
create table public.admin_profiles(user_id uuid primary key references auth.users(id) on delete cascade, role text not null check(role='admin'));
create table public.event_settings(id int primary key check(id=1),starts_at timestamptz not null default '2026-11-26 18:00:00+05',location text not null default 'School Grand Hall',description text not null default 'One extraordinary evening. A thousand unforgettable memories.',dress_code text not null default 'Black tie & evening gowns',registration_open boolean not null default true,registration_deadline timestamptz not null default '2026-11-26 12:00:00+05',voting_status text not null default 'closed' check(voting_status in('open','paused','closed')),results_published boolean not null default false,reveal_at timestamptz,tie_winner uuid,tie_procedure text);
insert into public.event_settings(id) values(1);
create sequence public.couple_number;
create table public.couple_applications(id uuid primary key default extensions.gen_random_uuid(),first_name text not null check(length(first_name) between 2 and 80),second_name text not null check(length(second_name) between 2 and 80),group_name text not null check(length(group_name) between 1 and 40),couple_name text not null default '' check(length(couple_name)<=80),contact text not null check(length(contact) between 3 and 160),consent boolean not null check(consent),status text not null default 'uploading' check(status in('uploading','pending','approved','rejected')),photo_path text not null default '',public_photo_path text not null default '',upload_hash text,upload_expires timestamptz,number int unique,sort_order int not null default 0,created_at timestamptz not null default now());
create table public.voting_sessions(id uuid primary key default extensions.gen_random_uuid(),created_at timestamptz not null default now(),label text not null default 'The Grand Ball 2026',active boolean not null default true);
create unique index one_active_session on public.voting_sessions(active) where active;
insert into public.voting_sessions default values;
create table public.voting_tickets(id uuid primary key default extensions.gen_random_uuid(),session_id uuid not null references public.voting_sessions(id),token_hash text unique not null,used_at timestamptz,revoked boolean not null default false,created_at timestamptz not null default now());
create table public.votes(id uuid primary key default extensions.gen_random_uuid(),ticket_id uuid not null unique references public.voting_tickets(id),couple_id uuid not null references public.couple_applications(id) on delete restrict,session_id uuid not null references public.voting_sessions(id),created_at timestamptz not null default now());
create index votes_couple_idx on public.votes(couple_id);
create table public.event_program(id bigint generated always as identity primary key,time text not null check(time ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'),title text not null check(length(title) between 1 and 100),description text not null default '' check(length(description)<=500),sort_order int not null default 0);
insert into public.event_program(time,title,description,sort_order) values('18:00','The grand arrival','Step into the evening. Find your place in the story.',0),('18:30','Let the ball begin','A royal welcome and the ceremonial opening.',1),('19:00','The first waltz','The floor is yours. Let the music lead.',2),('19:30','A little magic','Performances, surprises, and moments to remember.',3),('20:00','Crown the evening','Cast your vote for the best couple of the ball.',4),('20:30','The royal reveal','One unforgettable announcement. A well-deserved crown.',5),('21:00','One last dance','A beautiful ending. A memory that stays.',6);
create table public.gallery_images(id uuid primary key default extensions.gen_random_uuid(),url text not null,storage_path text not null,caption text not null check(length(caption) between 1 and 200),sort_order int not null default 0);
create table public.audit_log(id bigint generated always as identity primary key,actor uuid,action text not null,details jsonb not null default '{}',created_at timestamptz not null default now());
create function public.is_admin() returns boolean language sql stable security definer set search_path=public,pg_temp as $$select exists(select 1 from admin_profiles where user_id=auth.uid() and role='admin')$$;
create function public.require_admin() returns void language plpgsql security definer set search_path=public,pg_temp as $$begin if not is_admin() then raise exception 'Administrator access required' using errcode='42501';end if;end$$;
create function public.log_action(p_action text,p_details jsonb default '{}') returns void language sql security definer set search_path=public,pg_temp as $$insert into audit_log(actor,action,details) values(auth.uid(),p_action,p_details)$$;
-- RLS prevents all direct public writes; public reads are restricted to safe data.
alter table public.admin_profiles enable row level security;
alter table public.event_settings enable row level security;
alter table public.couple_applications enable row level security;
alter table public.voting_sessions enable row level security;
alter table public.voting_tickets enable row level security;
alter table public.votes enable row level security;
alter table public.event_program enable row level security;
alter table public.gallery_images enable row level security;
alter table public.audit_log enable row level security;
create policy admin_self on public.admin_profiles for select to authenticated using(user_id=auth.uid());
create policy settings_admin_read on public.event_settings for select to authenticated using(public.is_admin());
create view public.public_event_settings with(security_barrier=true) as select id,starts_at,location,description,dress_code,registration_open,registration_deadline,voting_status,results_published,reveal_at,null::uuid as tie_winner from public.event_settings;
grant select on public.public_event_settings to anon,authenticated;
create policy applications_admin on public.couple_applications for select to authenticated using(public.is_admin());
create policy tickets_admin on public.voting_tickets for select to authenticated using(public.is_admin());
create policy session_admin on public.voting_sessions for select to authenticated using(public.is_admin());
create policy program_read on public.event_program for select using(true);
create policy gallery_read on public.gallery_images for select using(true);
create policy audit_read on public.audit_log for select to authenticated using(public.is_admin());
-- Owner-owned view intentionally bypasses underlying RLS but exposes only approved, public columns.
create view public.approved_couples with(security_barrier=true) as select id,first_name,second_name,group_name,couple_name,public_photo_path as photo_path,number,sort_order,status from public.couple_applications where status='approved';
grant select on public.approved_couples to anon,authenticated;
create function public.submit_application(p_first text,p_second text,p_group text,p_name text,p_contact text,p_consent boolean,p_mime text,p_size bigint) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare s event_settings;v_id uuid;v_token text;begin
select * into s from event_settings where id=1 for share;
if not s.registration_open or now()>s.registration_deadline then raise exception 'Registration is closed';end if;
if not p_consent or p_consent is null then raise exception 'Participant permission is required';end if;
if p_mime not in('image/jpeg','image/png','image/webp') or p_size not between 1 and 5242880 then raise exception 'Invalid photograph';end if;
perform pg_advisory_xact_lock(hashtext(lower(trim(p_contact))));
if exists(select 1 from couple_applications where lower(contact)=lower(trim(p_contact)) and created_at>now()-interval '10 minutes') then raise exception 'An application was recently received for this contact. Please wait ten minutes before trying again.';end if;
v_token=encode(extensions.gen_random_bytes(24),'hex');
insert into couple_applications(first_name,second_name,group_name,couple_name,contact,consent,upload_hash,upload_expires) values(trim(p_first),trim(p_second),trim(p_group),trim(p_name),trim(p_contact),true,encode(extensions.digest(v_token,'sha256'),'hex'),now()+interval '15 minutes') returning id into v_id;
return jsonb_build_object('id',v_id,'upload_token',v_token);end$$;
create function public.valid_application_upload(p_path text) returns boolean language sql stable security definer set search_path=public,pg_temp as $$select exists(select 1 from couple_applications where id::text=split_part(p_path,'/',1) and status='uploading' and upload_expires>now() and upload_hash=encode(extensions.digest(split_part(split_part(p_path,'/',2),'.',1),'sha256'),'hex'))$$;
create function public.complete_application(p_id uuid,p_token text,p_path text) returns void language plpgsql security definer set search_path=public,pg_temp as $$begin
if not exists(select 1 from storage.objects where bucket_id='application-photos' and name=p_path) then raise exception 'Photograph upload was not confirmed. Please retry.';end if;
update couple_applications set status='pending',photo_path=p_path,upload_hash=null,upload_expires=null where id=p_id and status='uploading' and upload_expires>now() and upload_hash=encode(extensions.digest(p_token,'sha256'),'hex') and split_part(p_path,'/',1)=p_id::text and split_part(split_part(p_path,'/',2),'.',1)=p_token;
if not found then raise exception 'Application expired or could not be verified';end if;end$$;
create function public.moderate_couple(p_id uuid,p_status text) returns void language plpgsql security definer set search_path=public,pg_temp as $$declare c couple_applications;begin perform require_admin();if p_status not in('approved','rejected') then raise exception 'Invalid status';end if;select * into c from couple_applications where id=p_id for update;if not found or c.status='uploading' then raise exception 'Application is not ready';end if;
if p_status='approved' and c.public_photo_path='' then raise exception 'Upload or publish a participant-approved photograph first';end if;
if p_status='rejected' and exists(select 1 from votes where couple_id=p_id) then raise exception 'A couple with votes cannot be removed from the competition';end if;
update couple_applications set status=p_status,number=case when p_status='approved' then coalesce(number,nextval('couple_number')) else number end where id=p_id;perform log_action('moderate_couple',jsonb_build_object('couple',p_id,'status',p_status));end$$;
create function public.admin_save_couple(p_id uuid,p_data jsonb) returns void language plpgsql security definer set search_path=public,pg_temp as $$begin perform require_admin();if p_id is null then insert into couple_applications(first_name,second_name,group_name,couple_name,contact,consent,status,sort_order) values(p_data->>'first_name',p_data->>'second_name',p_data->>'group_name',coalesce(p_data->>'couple_name',''),p_data->>'contact',true,'pending',coalesce((p_data->>'sort_order')::int,0));else update couple_applications set first_name=p_data->>'first_name',second_name=p_data->>'second_name',group_name=p_data->>'group_name',couple_name=coalesce(p_data->>'couple_name',''),contact=p_data->>'contact',sort_order=coalesce((p_data->>'sort_order')::int,0) where id=p_id;end if;perform log_action('save_couple',jsonb_build_object('couple',p_id));end$$;
create function public.update_couple_photo(p_id uuid,p_path text) returns void language plpgsql security definer set search_path=public,pg_temp as $$begin perform require_admin();if split_part(p_path,'/',1)<>p_id::text or not exists(select 1 from storage.objects where bucket_id='couple-photos' and name=p_path) then raise exception 'Photograph has not been uploaded';end if;update couple_applications set public_photo_path=p_path where id=p_id;perform log_action('publish_couple_photo',jsonb_build_object('couple',p_id));end$$;
create function public.delete_couple(p_id uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$begin perform require_admin();delete from couple_applications where id=p_id;perform log_action('delete_couple',jsonb_build_object('couple',p_id));end$$;
create function public.generate_tickets(p_count int) returns text[] language plpgsql security definer set search_path=public,pg_temp as $$declare codes text[]='{}';token text;sid uuid;begin perform require_admin();if p_count not between 1 and 500 then raise exception 'Choose 1–500 tickets';end if;select id into sid from voting_sessions where active;for i in 1..p_count loop token=upper(encode(extensions.gen_random_bytes(10),'hex'));insert into voting_tickets(session_id,token_hash) values(sid,encode(extensions.digest(token,'sha256'),'hex'));codes=array_append(codes,token);end loop;perform log_action('generate_tickets',jsonb_build_object('count',p_count));return codes;end$$;
create function public.revoke_ticket(p_id uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$begin perform require_admin();update voting_tickets set revoked=true where id=p_id and used_at is null;if not found then raise exception 'Ticket was redeemed or does not exist';end if;perform log_action('revoke_ticket',jsonb_build_object('ticket',p_id));end$$;
create function public.cast_vote(p_code text,p_couple uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$declare t voting_tickets;s event_settings;begin
select * into s from event_settings where id=1 for share;
if s.voting_status<>'open' then raise exception 'Voting is not open';end if;
if length(p_code)<>20 then raise exception 'Invalid guest code';end if;
select * into t from voting_tickets where token_hash=encode(extensions.digest(upper(trim(p_code)),'sha256'),'hex') for update;
if not found or t.revoked or t.used_at is not null then raise exception 'This guest code is invalid, revoked, or already used';end if;
if not exists(select 1 from voting_sessions where id=t.session_id and active) then raise exception 'This guest ticket is for a closed session';end if;
perform 1 from couple_applications where id=p_couple and status='approved' for share;if not found then raise exception 'Couple is not eligible';end if;
insert into votes(ticket_id,couple_id,session_id) values(t.id,p_couple,t.session_id);
update voting_tickets set used_at=now() where id=t.id;end$$;
create function public.admin_results() returns table(couple_id uuid,votes bigint) language plpgsql stable security definer set search_path=public,pg_temp as $$begin perform require_admin();return query select c.id,count(v.id) from couple_applications c left join votes v on v.couple_id=c.id and v.session_id=(select id from voting_sessions where active) where c.status='approved' group by c.id;end$$;
create function public.public_results() returns table(couple_id uuid,votes bigint) language plpgsql stable security definer set search_path=public,pg_temp as $$begin if not (select results_published from event_settings where id=1) then raise exception 'Results have not been published';end if;return query select c.id,count(v.id) from couple_applications c left join votes v on v.couple_id=c.id and v.session_id=(select id from voting_sessions where active) where c.status='approved' group by c.id;end$$;
create function public.set_event_state(p_patch jsonb) returns void language plpgsql security definer set search_path=public,pg_temp as $$declare s event_settings;begin perform require_admin();select * into s from event_settings where id=1 for update;
if p_patch ? 'results_published' and (p_patch->>'results_published')::boolean and s.voting_status<>'closed' then raise exception 'Close voting before publishing results';end if;
if p_patch->>'voting_status' in('open','paused') and s.reveal_at is not null then raise exception 'Winner announcement is final. Voting cannot be reopened.';end if;
update event_settings set starts_at=coalesce((p_patch->>'starts_at')::timestamptz,starts_at),location=coalesce(p_patch->>'location',location),description=coalesce(p_patch->>'description',description),dress_code=coalesce(p_patch->>'dress_code',dress_code),registration_deadline=coalesce((p_patch->>'registration_deadline')::timestamptz,registration_deadline),registration_open=coalesce((p_patch->>'registration_open')::boolean,registration_open),voting_status=coalesce(p_patch->>'voting_status',voting_status),results_published=case when p_patch->>'voting_status' in('open','paused') then false else coalesce((p_patch->>'results_published')::boolean,results_published) end,tie_winner=case when p_patch->>'voting_status'='open' then null else tie_winner end where id=1;perform log_action('event_settings',p_patch);end$$;
create function public.set_tiebreak(p_couple uuid,p_reason text) returns void language plpgsql security definer set search_path=public,pg_temp as $$declare n bigint;topn bigint;leaders int;begin perform require_admin();perform 1 from event_settings where id=1 and voting_status='closed' and reveal_at is null for update;if not found then raise exception 'Close voting and resolve the tie before the reveal';end if;if length(trim(p_reason))<15 then raise exception 'Record the announced tie-break procedure';end if;
select max(votes) into topn from admin_results();select votes into n from admin_results() where couple_id=p_couple;select count(*) into leaders from admin_results() where votes=topn;
if n is null or n<>topn or n=0 or leaders<2 then raise exception 'Choose a tied first-place couple';end if;
update event_settings set tie_winner=p_couple,tie_procedure=p_reason where id=1;perform log_action('tiebreak',jsonb_build_object('couple',p_couple,'procedure',p_reason));end$$;
create function public.announce_winners() returns void language plpgsql security definer set search_path=public,pg_temp as $$begin perform require_admin();perform 1 from event_settings where id=1 and voting_status='closed' and reveal_at is null for update;if not found then raise exception 'Voting must be closed and the winner not yet announced';end if;if not exists(select 1 from votes v join voting_sessions s on v.session_id=s.id where s.active) then raise exception 'No validated votes';end if;update event_settings set results_published=true,reveal_at=now() where id=1;perform log_action('announce_winners');end$$;
create function public.public_winners() returns setof public.approved_couples language plpgsql stable security definer set search_path=public,pg_temp as $$begin if not exists(select 1 from event_settings where id=1 and results_published and reveal_at is not null) then return;end if;return query select c.* from approved_couples c join public_results() r on c.id=r.couple_id where r.votes=(select max(x.votes) from public_results() x) and r.votes>0 and ((select tie_winner from event_settings where id=1) is null or c.id=(select tie_winner from event_settings where id=1));end$$;
create function public.save_program(p_items jsonb) returns void language plpgsql security definer set search_path=public,pg_temp as $$begin perform require_admin();if jsonb_array_length(p_items)>50 then raise exception 'Too many activities';end if;delete from event_program;insert into event_program(time,title,description,sort_order) select x->>'time',x->>'title',coalesce(x->>'description',''),(x->>'sort_order')::int from jsonb_array_elements(p_items) x;perform log_action('save_program');end$$;
create function public.add_gallery(p_path text,p_caption text) returns void language plpgsql security definer set search_path=public,pg_temp as $$declare base text;begin perform require_admin();if not exists(select 1 from storage.objects where bucket_id='gallery' and name=p_path) then raise exception 'Upload not confirmed';end if;-- URL is built by the browser using its project URL after retrieval; keep a project-relative storage path here.
insert into gallery_images(url,storage_path,caption) values('/storage/v1/object/public/gallery/'||p_path,p_path,p_caption);perform log_action('add_gallery',jsonb_build_object('path',p_path));end$$;
create function public.delete_gallery(p_id uuid) returns void language plpgsql security definer set search_path=public,pg_temp as $$begin perform require_admin();delete from gallery_images where id=p_id;perform log_action('delete_gallery',jsonb_build_object('image',p_id));end$$;
-- Buckets restrict size and declared MIME. Organizers should review uploaded files before publication.
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('application-photos','application-photos',false,5242880,array['image/jpeg','image/png','image/webp']),('couple-photos','couple-photos',true,5242880,array['image/jpeg','image/png','image/webp']),('gallery','gallery',true,5242880,array['image/jpeg','image/png','image/webp']);
create policy application_upload on storage.objects for insert to anon,authenticated with check(bucket_id='application-photos' and public.valid_application_upload(name));
create policy application_admin_read on storage.objects for select to authenticated using(bucket_id='application-photos' and public.is_admin());
create policy media_admin_insert on storage.objects for insert to authenticated with check(bucket_id in('couple-photos','gallery') and public.is_admin());
create policy media_public_read on storage.objects for select using(bucket_id in('couple-photos','gallery'));
create policy media_admin_delete on storage.objects for delete to authenticated using(bucket_id in('application-photos','couple-photos','gallery') and public.is_admin());
-- Remove PostgreSQL's default PUBLIC EXECUTE grant from every application function.
revoke execute on all functions in schema public from public,anon,authenticated;
grant execute on function public.is_admin(),public.valid_application_upload(text),public.submit_application(text,text,text,text,text,boolean,text,bigint),public.complete_application(uuid,text,text),public.cast_vote(text,uuid),public.public_results(),public.public_winners() to anon,authenticated;
grant execute on function public.moderate_couple(uuid,text),public.admin_save_couple(uuid,jsonb),public.update_couple_photo(uuid,text),public.delete_couple(uuid),public.generate_tickets(int),public.revoke_ticket(uuid),public.admin_results(),public.set_event_state(jsonb),public.set_tiebreak(uuid,text),public.announce_winners(),public.save_program(jsonb),public.add_gallery(text,text),public.delete_gallery(uuid) to authenticated;
revoke all on public.votes,public.voting_tickets,public.couple_applications,public.audit_log,public.admin_profiles,public.voting_sessions from anon,authenticated;
grant select on public.couple_applications,public.audit_log,public.admin_profiles,public.voting_sessions to authenticated;
grant select(id,used_at,revoked,created_at,session_id) on public.voting_tickets to authenticated;
revoke all on public.event_settings from anon,authenticated;
grant select on public.event_settings to authenticated;
grant select on public.event_program,public.gallery_images to anon,authenticated;
commit;
